class RectangularPrism:
    def __init__(self, width, length, height):
        self.width = width
        self.length = length
        self.height = height

    def base_area(self):
        return self.width * self.length

    def is_square_base(self):
        return self.width == self.length

    def volume(self):
        return self.base_area * self.height

